import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "../../axiosInstance";

const API_BASE_URL = "/api/v1/buyer-seller-connections";

// Create Buyer-Seller Connection
export const createBuyerSellerConnection = createAsyncThunk(
  "buyerNetwork/createBuyerSellerConnection",
  async ({ buyerEmail, buyerPhone, buyerCategory }, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem("token");
      const response = await axios.post(
        `${API_BASE_URL}/connection`,
        { buyerEmail, buyerPhone, buyerCategory },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      return response.data.data;
    } catch (error) {
      return rejectWithValue(
        error.response?.data?.message ||
          "Failed to create buyer-seller connection"
      );
    }
  }
);

// Fetch Buyer Connections
export const fetchBuyerConnections = createAsyncThunk(
  "buyerNetwork/fetchBuyerConnections",
  async ({ page = 1, limit = 10 }, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem("token");
      // API call with query strings
      const response = await axios.get(`${API_BASE_URL}/connection?page=${page}&limit=${limit}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      const { data, totalPages, totalConnections } = response.data;

      const formattedConnections = data.map((conn) => ({
        _id: conn._id,
        initials: getInitials(conn.otherUser?.name || "BU"),
        name: conn.otherUser?.name || "Unknown User",
        email: conn.otherUser?.email || "-",
        phone: conn.otherUser?.phone || "-",
        company: conn.otherUser?.businessName || "N/A",
        city: conn.otherUser?.businessAddress || "Jaipur",
        status: conn.status,
        buyerCategory: conn.buyerCategory?.name || "N/A",
        connectionData: conn,
        buyerId: conn.otherUser?._id,
      }));
      return { formattedConnections, totalPages, totalConnections };
    } catch (error) {
      return rejectWithValue(error.response?.data?.message || "Failed to fetch");
    }
  }
);

// Update Connection Status (Accept / Reject / Restore)
export const updateConnectionStatus = createAsyncThunk(
  "buyerNetwork/updateConnectionStatus",
  async ({ connectionId, status }, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem("token");
      const response = await axios.put(
        `${API_BASE_URL}/connection/${connectionId}/status`,
        { status },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      return response.data.data;
    } catch (error) {
      return rejectWithValue(
        error.response?.data?.message ||
          "Failed to update connection status"
      );
    }
  }
);

// Assign / Update Buyer Category (Direct Accepted)
export const assignBuyerCategory = createAsyncThunk(
  "buyerNetwork/assignBuyerCategory",
  async ({ buyerEmail, buyerPhone, buyerCategory }, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem("token");

      const response = await axios.post(
        `${API_BASE_URL}/assign/category`, 
        { buyerEmail, buyerPhone, buyerCategory },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      return response.data.data; // connection object
    } catch (error) {
      return rejectWithValue(
        error.response?.data?.message || "Failed to assign buyer category"
      );
    }
  }
);


const initialState = {
  buyers: [],
  tabValue: 0,
  searchValue: "",
  loading: false,
  error: null,
  totalPages: 1, 
  totalConnections: 0 
};

const buyerNetworkSlice = createSlice({
  name: "buyerNetwork",
  initialState,
  reducers: {
    setTabValue(state, action) {
      state.tabValue = action.payload;
    },
    setSearchValue(state, action) {
      state.searchValue = action.payload;
    },
    addNewConnection(state, action) {
      const newConnection = action.payload;
      state.buyers.unshift({
        _id: newConnection._id,
        initials: getInitials(newConnection?.buyerEmail || "BU"),
        name:
          newConnection?.otherUser?.name ||
          newConnection?.buyerEmail ||
          "Unknown User",
        email: newConnection?.otherUser?.email || newConnection?.buyerEmail,
        phone: newConnection?.otherUser?.phone || newConnection?.buyerPhone,
        city: newConnection?.otherUser?.businessAddress || "Bangalore",
        status: newConnection.status || "Pending",
        connectionData: newConnection,
      });
    },
    clearError(state) {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchBuyerConnections.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchBuyerConnections.fulfilled, (state, action) => {
        state.loading = false;
        state.buyers = action.payload.formattedConnections;
        state.totalPages = action.payload.totalPages; // Update total pages
        state.totalConnections = action.payload.totalConnections;
      })
      .addCase(fetchBuyerConnections.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })

      // Create Buyer-Seller Connection
      .addCase(createBuyerSellerConnection.pending, (state) => {
        state.loading = true;
      })
      .addCase(createBuyerSellerConnection.fulfilled, (state, action) => {
        state.loading = false;
        const newConn = action.payload;
        state.buyers.unshift({
          _id: newConn._id,
          initials: getInitials(newConn?.otherUser?.name || "BU"),
          name: newConn?.otherUser?.name || newConn?.buyerEmail || "Unknown",
          email: newConn?.otherUser?.email || newConn?.buyerEmail || "-",
          phone: newConn?.otherUser?.phone || newConn?.buyerPhone || "-",
          city: newConn?.otherUser?.businessAddress || "Bangalore",
          status: newConn.status || "Pending",
          connectionData: newConn,
        });
      })
      .addCase(createBuyerSellerConnection.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })

      // Update Connection Status
      .addCase(updateConnectionStatus.fulfilled, (state, action) => {
        const updated = action.payload;
        const index = state.buyers.findIndex((b) => b._id === updated._id);
        if (index !== -1) {
          state.buyers[index].status = updated.status;
        }
      })
      // Assign Buyer Category
.addCase(assignBuyerCategory.pending, (state) => {
  state.loading = true;
  state.error = null;
})
.addCase(assignBuyerCategory.fulfilled, (state, action) => {
  state.loading = false;

  const updatedConn = action.payload;

  const index = state.buyers.findIndex(
    (b) => b._id === updatedConn._id
  );

  if (index !== -1) {
    // ✅ Existing buyer → UPDATE
    state.buyers[index] = {
      ...state.buyers[index],
      status: updatedConn.status, // Accepted
      buyerCategory: updatedConn.buyerCategory?.name || "N/A",
      connectionData: updatedConn,
    };
  } else {
    // ✅ New buyer → ADD
    state.buyers.unshift({
      _id: updatedConn._id,
      initials: getInitials(updatedConn?.otherUser?.name || "BU"),
      name:
        updatedConn?.otherUser?.name ||
        updatedConn?.buyerEmail ||
        "Unknown User",
      email: updatedConn?.otherUser?.email || updatedConn?.buyerEmail,
      phone: updatedConn?.otherUser?.phone || updatedConn?.buyerPhone,
      city: updatedConn?.otherUser?.businessAddress || "Bangalore",
      status: updatedConn.status || "Accepted",
      buyerCategory: updatedConn.buyerCategory?.name || "N/A",
      connectionData: updatedConn,
    });
  }
})
.addCase(assignBuyerCategory.rejected, (state, action) => {
  state.loading = false;
  state.error = action.payload;
})

  },
});

// Helper function to get initials
const getInitials = (name) => {
  if (!name) return "BU";
  return name
    .split(" ")
    .map((word) => word[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);
};

export const { setTabValue, setSearchValue, addNewConnection, clearError } =
  buyerNetworkSlice.actions;
export default buyerNetworkSlice.reducer;
