import React, { useEffect, useState } from "react";
import {
  Box,
  Typography,
  Button,
  Card,
  CardContent,
  Grid,
  useTheme,
  useMediaQuery,
  CircularProgress,
  Select,
  MenuItem,
  Dialog,
  DialogContent,
  DialogActions,
  Pagination,
} from "@mui/material";
import { useSelector, useDispatch } from "react-redux";
import { toast } from "react-toastify";
import {
  setSearchValue,
  fetchBuyerConnections,
  updateConnectionStatus,
  clearError,
  assignBuyerCategory,
} from "../redux/slices/buyerNetworkSlice";
import { getAllBuyerCategories } from "../redux/slices/buyerCategoriesSlice";
import FindNewBuyerModal from "./FindNewBuyerModal";
import { useNavigate } from "react-router-dom";

export default function BuyerNetwork() {
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const dispatch = useDispatch();
  const [openFindBuyer, setOpenFindBuyer] = useState(false);
  const { buyers, tabValue, searchValue, loading, error, totalPages } =
    useSelector((state) => state.buyerNetwork);
  const [selectedCategories, setSelectedCategories] = useState({});
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [selectedBuyer, setSelectedBuyer] = useState(null);
  const [pendingCategory, setPendingCategory] = useState("");
  const [page, setPage] = useState(1);
  const itemsPerPage = 10;
  const [chatOpen, setChatOpen] = useState(false);
const [activeBuyerId, setActiveBuyerId] = useState(null);


  useEffect(() => {
    dispatch(fetchBuyerConnections({ page, limit: itemsPerPage }));
  }, [dispatch, page]);

  const { categories: buyerCategories } = useSelector(
    (state) => state.buyerCategories
  );

  useEffect(() => {
    dispatch(getAllBuyerCategories());
  }, [dispatch]);

  // Show toast for errors
  useEffect(() => {
    if (error) {
      toast.error(error);
      dispatch(clearError());
    }
  }, [error, dispatch]);

  // Handle connection status update (works if updateConnectionStatus is thunk or plain action)
  // const handleStatusUpdate = (connectionId, status) => {
  //   const result = dispatch(updateConnectionStatus({ connectionId, status }));

  //   // if the dispatched action returns a promise (createAsyncThunk), refresh after it's done
  //   if (result && typeof result.then === "function") {
  //     result
  //       .then(() => {
  //         dispatch(fetchBuyerConnections());
  //         toast.success(`Status updated to ${status}`);
  //       })
  //       .catch((err) => {
  //         // optional: you already show error from redux slice, but keep console for debugging
  //         console.error("updateConnectionStatus failed:", err);
  //       });
  //   } else {
  //     // if not a promise, still refresh (best effort)
  //     // dispatch(fetchBuyerConnections());
  //     toast.success(`Status updated to ${status}`);
  //   }
  // };

  // const filteredBuyers = buyers?.filter((b) =>
  //   b.name?.toLowerCase().includes(searchValue?.toLowerCase())
  // );

  //  Search logic (Filter only on current page data)
  const filteredBuyers = buyers?.filter(
    (b) =>
      b.name?.toLowerCase().includes(searchValue?.toLowerCase()) ||
      b.city?.toLowerCase().includes(searchValue?.toLowerCase()) ||
      b.email?.toLowerCase().includes(searchValue?.toLowerCase()) ||
      b.company?.toLowerCase().includes(searchValue?.toLowerCase())
  );

  const handlePageChange = (event, value) => {
    setPage(value);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const getStatusStyle = (status) => {
    switch (status) {
      case "Accepted":
        return { bg: "#dcfce7", color: "#166534", label: "Connected" };
      case "Pending":
        return { bg: "#fef3c7", color: "#92400e", label: "Pending" };
      case "Rejected":
        return { bg: "#fee2e2", color: "#991b1b", label: "Rejected" };
      default:
        return { bg: "#e5e7eb", color: "#374151", label: status };
    }
  };

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        background: "#f8fafc",
        px: { xs: 2, sm: 4, md: 7, lg: 12 },
        py: { xs: 2, sm: 4, md: 5 },
        boxSizing: "border-box",
        display: "flex",
        justifyContent: "center",
      }}
    >
      <Box
        sx={{
          width: "100%",
          maxWidth: 1400,
          mx: "auto",
          px: { xs: 1, sm: 3, md: 4 },
          boxSizing: "border-box",
        }}
      >
        {/* Title and Tabs */}
        <Box sx={{ mb: 3 }}>
          <Box
            sx={{
              mb: 3,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <Typography variant="h6" fontWeight={700} sx={{ color: "#222" }}>
              Buyer Network
            </Typography>
          </Box>

          {/* Modal */}
          <FindNewBuyerModal
            open={openFindBuyer}
            onClose={() => setOpenFindBuyer(false)}
          />

          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              mb: 1,
              flexWrap: "wrap",
            }}
          >
            <Box
              sx={{
                flex: 1,
                minWidth: isMobile ? "100%" : 240,
                ml: isMobile ? 0 : 1,
                mt: isMobile ? 1 : 0,
              }}
            >
              <input
                type="text"
                placeholder="Search buyers..."
                value={searchValue}
                onChange={(e) => dispatch(setSearchValue(e.target.value))}
                style={{
                  width: "100%",
                  fontSize: 15,
                  borderRadius: 6,
                  border: "1px solid #e0e0e0",
                  padding: "8px 12px",
                  outline: "none",
                }}
              />
            </Box>
          </Box>
        </Box>

        {/* Loading State */}
        {loading && (
          <Box sx={{ display: "flex", justifyContent: "center", py: 4 }}>
            <CircularProgress />
          </Box>
        )}

        {/* Buyers Grid */}
        {/* Buyers Grid */}
        {!loading && (
          <Grid
            container
            spacing={isMobile ? 3 : 4}
            justifyContent="flex-start"
            sx={{ px: { xs: 1, sm: 0 } }}
          >
            {/* Connect New Buyer – FIRST CARD */}
            <Grid item xs={12} sm={12} md={6} lg={4}>
              <Box
                onClick={() => setOpenFindBuyer(true)}
                sx={{
                  height: "100%",
                  minHeight: 300,
                  borderRadius: 3,
                  border: "1.5px solid #e5e7eb",
                  background: "#f9fafb",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: "pointer",
                  transition: "all 0.25s ease",
                  "&:hover": {
                    border: "2px dashed #3b82f6",
                    background: "#f0f6ff",
                  },
                }}
              >
                <Box
                  sx={{
                    width: 42,
                    height: 42,
                    borderRadius: "50%",
                    background: "#3b82f6",
                    color: "#fff",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 22,
                    mb: 1,
                  }}
                >
                  +
                </Box>
                <Typography
                  fontWeight={600}
                  sx={{ color: "#3b82f6", fontSize: 16 }}
                >
                  Connect New Buyer
                </Typography>
              </Box>
            </Grid>

            {filteredBuyers.length === 0 ? (
              <Box sx={{ width: "100%", textAlign: "center", py: 6 }}>
                <Typography variant="body1" color="text.secondary">
                  {tabValue === 0
                    ? "No connected buyers found."
                    : tabValue === 1
                    ? "No pending requests."
                    : "No rejected requests."}
                </Typography>
              </Box>
            ) : (
              filteredBuyers.map((buyer) => (
                <Grid key={buyer._id} item xs={12} sm={12} md={6} lg={4}>
                  <Card
                    elevation={0}
                    sx={{
                      borderRadius: 3,
                      boxShadow: "0px 6px 18px rgba(0,0,0,0.06)",
                    }}
                  >
                    <CardContent sx={{ p: 3, position: "relative" }}>
                      {/* STATUS BADGE */}
                      {(() => {
                        const statusStyle = getStatusStyle(buyer.status);
                        return (
                          <Box
                            sx={{
                              position: "absolute",
                              top: 12,
                              right: 12,
                              px: 1.5,
                              py: 0.5,
                              borderRadius: 2,
                              fontSize: 12,
                              fontWeight: 700,
                              backgroundColor: statusStyle.bg,
                              color: statusStyle.color,
                            }}
                          >
                            {statusStyle.label}
                          </Box>
                        );
                      })()}

                      {/* Avatar */}
                      <Box
                        sx={{
                          display: "flex",
                          justifyContent: "center",
                          mb: 2,
                        }}
                      >
                        <Box
                          component="img"
                          src={
                            buyer.profileImage ||
                            "https://via.placeholder.com/60"
                          }
                          sx={{ width: 60, height: 60, borderRadius: "50%" }}
                        />
                      </Box>

                      {/* Name */}
                      <Typography
                        fontWeight={700}
                        fontSize={16}
                        textAlign="center"
                      >
                        {buyer.name}
                      </Typography>

                      {/* Company */}
                      <Typography
                        variant="body2"
                        textAlign="center"
                        sx={{ color: "#6b7280", mb: 2 }}
                      >
                        {buyer.company || buyer.city}
                      </Typography>

                      {/* Category */}
                      <Typography
                        variant="caption"
                        sx={{ color: "#9ca3af", fontWeight: 600 }}
                      >
                        ASSIGNED CATEGORY
                      </Typography>
                      <Select
                        fullWidth
                        size="small"
                        value={
                          selectedCategories[buyer._id] ??
                          buyer.buyerCategory ??
                          ""
                        }
                        sx={{
                          mt: 0.5,
                          mb: 2,
                          borderRadius: 2,
                          fontSize: 14,
                          backgroundColor: "#fff",
                        }}
                        onChange={(e) => {
                          const newCategory = e.target.value;
                          setSelectedBuyer(buyer);
                          setPendingCategory(newCategory);
                          setConfirmOpen(true);
                        }}
                      >
                        {buyerCategories?.map((cat) => (
                          <MenuItem key={cat._id} value={cat.name}>
                            {cat.name}
                          </MenuItem>
                        ))}
                      </Select>

                      {/* Actions */}
                      <Box sx={{ display: "flex", gap: 1 }}>
                        <Button
                          fullWidth
                          variant="contained"
                          sx={{
                            bgcolor: "#eef2ff",
                            color: "#3066be",
                            fontWeight: 600,
                            boxShadow: "none",
                            "&:hover": { bgcolor: "#e0e7ff" },
                          }}
                          onClick={() =>
                            navigate("/seller-dashboard/view-ledger", {
                              state: { buyerId: buyer.buyerId },
                            })
                          }
                        >
                          View Ledger
                        </Button>

                        {/* <Button
                          fullWidth
                          variant="outlined"
                          sx={{ fontWeight: 600 }}
                        >
                          Message
                        </Button> */}
                        <Button
  fullWidth
  variant="outlined"
  sx={{ fontWeight: 600 }}
  onClick={() => {
    setActiveBuyerId(buyer.buyerId);
    setChatOpen(true);
  }}
>
  Message
</Button>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>
              ))
            )}
          </Grid>
        )}
        {/* Pagination */}
        {!loading && buyers.length > 0 && (
          <Box
            sx={{
              display: "flex",
              justifyContent: "center",
              mt: 6,
              pb: 4,
            }}
          >
            <Pagination
              count={totalPages}
              page={page}
              onChange={handlePageChange}
              color="primary"
              size={isMobile ? "small" : "medium"}
              shape="rounded"
              showFirstButton
              showLastButton
            />
          </Box>
        )}
      </Box>
      <Dialog open={confirmOpen} onClose={() => setConfirmOpen(false)}>
        <DialogContent>
          <Typography>
            Are you sure you want to assign category "{pendingCategory}" to "
            {selectedBuyer?.name}"?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setConfirmOpen(false)} variant="outlined">
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={async () => {
              if (!selectedBuyer) return;
              const selectedCategoryObj = buyerCategories.find(
                (c) => c.name === pendingCategory
              );
              const payload = {
                buyerEmail: selectedBuyer.email || null,
                buyerPhone: selectedBuyer.email ? null : selectedBuyer.phone,
                buyerCategory: selectedCategoryObj?._id,
              };
              try {
                const resultAction = await dispatch(
                  assignBuyerCategory(payload)
                );
                if (assignBuyerCategory.fulfilled.match(resultAction)) {
                  dispatch(fetchBuyerConnections());
                  toast.success("Buyer category updated");
                } else {
                  toast.error(resultAction.payload || "Update failed");
                }
              } catch (err) {
                console.error(err);
              } finally {
                setConfirmOpen(false);
                setSelectedBuyer(null);
                setPendingCategory("");
              }
            }}
          >
            Confirm
          </Button>
        </DialogActions>
      </Dialog>

    </Box>
  );
}
