                      display: 'flex',
                      alignItems: 'center',
                      gap: 1.5,
                      px: 2.5, py: 1.5,
                      borderRadius: '50px',
                      border: `1px solid #EAECF0`,
                      bgcolor: '#fff',
                      transition: 'all 0.3s ease',
                      boxShadow: '1px 2px 0px -1px rgba(0, 0, 0, 0.05)', 
